        'position': encOffset(v.position),
        'buttons': v.buttons,
        'obscured': v.obscured,
        'pressure': fuseNum(v.pressure),
        'pressureMin': fuseNum(v.pressureMin),
        'pressureMax': fuseNum(v.pressureMax),
        'distance': fuseNum(v.distance),
        'distanceMax': fuseNum(v.distanceMax),
        'size': fuseNum(v.size),
        'radiusMajor': fuseNum(v.radiusMajor),
        'radiusMinor': fuseNum(v.radiusMinor),
        'radiusMin': fuseNum(v.radiusMin),
        'radiusMax': fuseNum(v.radiusMax),
        'orientation': fuseNum(v.orientation),
        'tilt': fuseNum(v.tilt),
        'embedderId': v.embedderId,
      };

Map<String, Object?>? encScaleEndDetails(ScaleEndDetails? v) => v == null
    ? null
    : {
        'velocity': encVelocity(v.velocity),
        'scaleVelocity': fuseNum(v.scaleVelocity),
        'pointerCount': v.pointerCount,
      };

